item.command:
/bin/bash -lc "python - <<'PY'
import os, json
from bioblend.galaxy import GalaxyInstance
key=open(os.environ['GALAXY_API_KEY_FILE']).read().strip()
gi=GalaxyInstance(os.environ['GALAXY_URL'], key=key)
tool='toolshed.g2.bx.psu.edu/repos/iuc/hisat2/hisat2/2.2.3+galaxy0'
data=gi.tools.show_tool(tool, io_details=True)
# find reference_genome conditional and index options
for inp in data['inputs']:
    if inp['name']=='reference_genome':
        cases=inp.get('cases',[])
        for case in cases:
            if case.get('value')=='indexed':
                for ci in case['inputs']:
                    if ci['name']=='index':
                        opts=ci.get('options',[])
                        matches=[o for o in opts if 'sapiens' in o[0].lower() or 'hg' in o[0].lower() or 'grch' in o[0].lower()]
                        print('human options count', len(matches))
                        for o in matches[:100]: print(o)
PY"

